/**
 * Broker OS database schema (Drizzle ORM, Postgres).
 *
 * Conventions every table follows:
 *  - id: uuid primary key, generated by the database
 *  - workspace_id: every row belongs to exactly one workspace (the sharing unit)
 *  - created_at / updated_at: timestamps with time zone
 *  - money: numeric(14,2); rates: numeric(6,3); calendar dates: date (YYYY-MM-DD strings)
 *
 * Later versions add claims, tower_layers, contract_requirements, certificates,
 * submissions, quotes, quote_options, tasks and activities via new migrations.
 * Keep the helper column factories below so those tables stay consistent.
 */
import { relations, sql } from "drizzle-orm";
import {
  date,
  index,
  integer,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uuid,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";
import {
  ACCOUNT_STATUSES,
  ENDORSEMENTS,
  EXPOSURE_BASES,
  LINES_OF_BUSINESS,
  RENEWAL_STATUSES,
} from "@/lib/constants";

export const accountStatusEnum = pgEnum("account_status", ACCOUNT_STATUSES);
export const lineOfBusinessEnum = pgEnum("line_of_business", LINES_OF_BUSINESS);
export const exposureBasisEnum = pgEnum("exposure_basis", EXPOSURE_BASES);
export const renewalStatusEnum = pgEnum("renewal_status", RENEWAL_STATUSES);
export const endorsementEnum = pgEnum("endorsement", ENDORSEMENTS);

/** Column helpers so every table shares the same audit columns and types. */
const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};
const money = (name: string) => numeric(name, { precision: 14, scale: 2, mode: "number" });
const rate = (name: string) => numeric(name, { precision: 6, scale: 3, mode: "number" });

export const workspaces = pgTable("workspaces", {
  id: uuid("id").primaryKey().defaultRandom(),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  asOfDate: date("as_of_date", { mode: "string" }).notNull(),
  ...timestamps,
});

export const accounts = pgTable(
  "accounts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    industry: text("industry").notNull(),
    annualRevenue: money("annual_revenue"),
    employeeCount: integer("employee_count"),
    province: text("province").notNull(),
    producer: text("producer"),
    accountManager: text("account_manager"),
    status: accountStatusEnum("status").notNull().default("prospect"),
    notes: text("notes"),
    ...timestamps,
  },
  (t) => [index("accounts_workspace_idx").on(t.workspaceId), index("accounts_workspace_name_idx").on(t.workspaceId, t.name)],
);

export const contacts = pgTable(
  "contacts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    role: text("role"),
    email: text("email"),
    phone: text("phone"),
    ...timestamps,
  },
  (t) => [index("contacts_account_idx").on(t.accountId), index("contacts_workspace_idx").on(t.workspaceId)],
);

export const policies = pgTable(
  "policies",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: uuid("workspace_id")
      .notNull()
      .references(() => workspaces.id, { onDelete: "cascade" }),
    accountId: uuid("account_id")
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    carrier: text("carrier").notNull(),
    lineOfBusiness: lineOfBusinessEnum("line_of_business").notNull(),
    policyNumber: text("policy_number"),
    effectiveDate: date("effective_date", { mode: "string" }).notNull(),
    expiryDate: date("expiry_date", { mode: "string" }).notNull(),
    occurrenceLimit: money("occurrence_limit"),
    aggregateLimit: money("aggregate_limit"),
    deductible: money("deductible"),
    annualPremium: money("annual_premium").notNull(),
    commissionRate: rate("commission_rate").notNull(),
    exposureBasis: exposureBasisEnum("exposure_basis").notNull(),
    exposureAmount: money("exposure_amount"),
    endorsements: endorsementEnum("endorsements")
      .array()
      .notNull()
      .default(sql`'{}'::endorsement[]`),
    renewalStatus: renewalStatusEnum("renewal_status").notNull().default("not_started"),
    previousPolicyId: uuid("previous_policy_id").references((): AnyPgColumn => policies.id, { onDelete: "set null" }),
    notes: text("notes"),
    ...timestamps,
  },
  (t) => [
    index("policies_account_idx").on(t.accountId),
    index("policies_workspace_idx").on(t.workspaceId),
    index("policies_workspace_expiry_idx").on(t.workspaceId, t.expiryDate),
  ],
);

export const workspacesRelations = relations(workspaces, ({ many }) => ({
  accounts: many(accounts),
  contacts: many(contacts),
  policies: many(policies),
}));

export const accountsRelations = relations(accounts, ({ one, many }) => ({
  workspace: one(workspaces, { fields: [accounts.workspaceId], references: [workspaces.id] }),
  contacts: many(contacts),
  policies: many(policies),
}));

export const contactsRelations = relations(contacts, ({ one }) => ({
  account: one(accounts, { fields: [contacts.accountId], references: [accounts.id] }),
}));

export const policiesRelations = relations(policies, ({ one }) => ({
  account: one(accounts, { fields: [policies.accountId], references: [accounts.id] }),
  previousPolicy: one(policies, {
    fields: [policies.previousPolicyId],
    references: [policies.id],
    relationName: "previousPolicy",
  }),
}));

export type Workspace = typeof workspaces.$inferSelect;
export type Account = typeof accounts.$inferSelect;
export type NewAccount = typeof accounts.$inferInsert;
export type Contact = typeof contacts.$inferSelect;
export type NewContact = typeof contacts.$inferInsert;
export type Policy = typeof policies.$inferSelect;
export type NewPolicy = typeof policies.$inferInsert;
